Ltac cs_crush :=
  repeat first [ assumption
               | exact I
               | apply cs_rset | apply cs_with_pc | apply cs_with_resv | apply cs_with_fcsr | apply cs_fset | apply cs_fwrite
               | apply cs_accrue | apply cs_inval_resv | apply load_val_ok | apply store_val_ok | apply exec_csr_ok
               | progress (cbn [eff_ok])
               | progress intros
               | match goal with
                 | |- context [match ?x with _ => _ end] => destruct x
                 end ].

